                if R + 1 > cur:
                    cur = R + 1
                if cur > n:            # 整条街已完全覆盖
                    return True
            return cur > n

        lo, hi = 0, n + m
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        out_lines.append(str(lo))

